// Input validation
function validateNotificationData(notificationData) {
  if (!notificationData || typeof notificationData !== 'object') {
    throw new Error('Invalid notification data');
  }

  if (!notificationData.title || !notificationData.body) {
    throw new Error('Title and body are required');
  }

  // Sanitize content
  return {
    title: notificationData.title.substring(0, 100),
    body: notificationData.body.substring(0, 500),
    type: notificationData.type || 'general'
  };
}

// Secure function call
exports.sendNotification = functions.https.onCall(async (data, context) => {
  // Verify authentication
  if (!context.auth) {
    throw new functions.https.HttpsError('unauthenticated', 'User must be authenticated');
  }

  // Validate and sanitize input
  const sanitizedData = validateNotificationData(data.notificationData);

  // Proceed with notification
  await sendNotification(data.teacherId, sanitizedData);
});

