// Token validation before sending
async function validateAndSendNotification(teacherId, notificationData) {
  const teacherDoc = await db.collection('teachers').doc(teacherId).get();

  if (!teacherDoc.exists) {
    throw new Error('Teacher not found');
  }

  const teacherData = teacherDoc.data();
  const fcmToken = teacherData.fcm_token;

  if (!fcmToken) {
    throw new Error('No FCM token available');
  }

  // Check token age (optional)
  const tokenAge = Date.now() - teacherData.token_updated?.toDate()?.getTime();
  if (tokenAge > 30 * 24 * 60 * 60 * 1000) { // 30 days
    console.warn('FCM token may be stale for teacher:', teacherId);
  }

  // Proceed with notification
  const message = {
    token: fcmToken,
    notification: notificationData,
    data: { type: notificationData.type || 'general' }
  };

  await admin.messaging().send(message);
}

async function sendBatchNotifications(teacherIds, notificationData) {
  const batchSize = 500; // FCM batch limit
  const batches = [];

  // Split teachers into batches
  for (let i = 0; i < teacherIds.length; i += batchSize) {
    batches.push(teacherIds.slice(i, i + batchSize));
  }

  const results = [];

  for (const batch of batches) {
    try {
      // Get all teacher documents in batch
      const teacherDocs = await Promise.all(
        batch.map(id => db.collection('teachers').doc(id).get())
      );

      // Build messages for valid teachers
      const messages = teacherDocs
        .filter(doc => doc.exists && doc.data().fcm_token)
        .map(doc => ({
          token: doc.data().fcm_token,
          notification: notificationData,
          data: { 
            type: notificationData.type || 'general',
            teacher_id: doc.id
          }
        }));

      // Send batch
      if (messages.length > 0) {
        const batchResponse = await admin.messaging().sendAll(messages);

        // Process batch results
        batchResponse.responses.forEach((response, index) => {
          results.push({
            teacherId: batch[index],
            success: response.success,
            error: response.error?.message
          });
        });
      }
    } catch (error) {
      console.error('Batch sending failed:', error);
      // Mark entire batch as failed
      batch.forEach(teacherId => {
        results.push({
          teacherId,
          success: false,
          error: error.message
        });
      });
    }
  }

  return results;
}

// Notification type definitions
const NOTIFICATION_TYPES = {
  WELLNESS: 'wellness',
  PEER_CONNECTION: 'peer_connection',
  SYSTEM_UPDATE: 'system_update',
  GENERAL: 'general',
  CHALLENGE: 'challenge',
  ACHIEVEMENT: 'achievement'
};

// Type-specific notification handling
async function sendTypedNotification(teacherId, type, customData) {
  let notificationData;

  switch (type) {
    case NOTIFICATION_TYPES.WELLNESS:
      notificationData = {
        title: 'Wellness Alert',
        body: customData.message || 'Check your wellness status',
        type: 'wellness',
        data: {
          stress_level: customData.stressLevel,
          recommendation: customData.recommendation
        }
      };
      break;

    case NOTIFICATION_TYPES.PEER_CONNECTION:
      notificationData = {
        title: 'New Peer Connection',
        body: `${customData.peerName} wants to connect with you`,
        type: 'peer_connection',
        data: {
          peer_id: customData.peerId,
          connection_type: customData.connectionType
        }
      };
      break;

    case NOTIFICATION_TYPES.CHALLENGE:
      notificationData = {
        title: 'New Challenge Available',
        body: customData.challengeTitle,
        type: 'challenge',
        data: {
          challenge_id: customData.challengeId,
          difficulty: customData.difficulty
        }
      };
      break;

    default:
      notificationData = {
        title: customData.title || 'VidyaNXT Update',
        body: customData.body || 'You have a new update',
        type: 'general'
      };
  }

  await sendNotification(teacherId, notificationData);
}

