// Analytics query functions
async function getNotificationStats(timeframe = 24) {
  const hoursAgo = new Date(Date.now() - timeframe * 60 * 60 * 1000);

  const snapshot = await db.collection('notification_metrics')
    .where('created_at', '>=', hoursAgo)
    .get();

  const stats = {
    total: 0,
    sent: 0,
    failed: 0,
    averageDuration: 0,
    typeBreakdown: {}
  };

  let totalDuration = 0;

  snapshot.forEach(doc => {
    const data = doc.data();
    stats.total++;

    if (data.status === 'sent') {
      stats.sent++;
    } else if (data.status === 'failed') {
      stats.failed++;
    }

    if (data.duration) {
      totalDuration += data.duration;
    }

    const type = data.type || 'general';
    stats.typeBreakdown[type] = (stats.typeBreakdown[type] || 0) + 1;
  });

  stats.averageDuration = stats.total > 0 ? totalDuration / stats.total : 0;
  stats.successRate = stats.total > 0 ? (stats.sent / stats.total) * 100 : 0;

  return stats;
}
